ST.xhtml:p:
(*第一阶段：确保圆管稳固同心且水平，转动360度，Z轴变化浮动不超过XX,则表示水平度较好*)
(*第二阶段：高处关随动检测Z轴高度*)
(*第三阶段：通过在最高点，获取卡盘中心Z轴的坐标*)


(*第一阶段*)
R_Circle360Trigger(CLK := g_bCircle360CenterM);
R_Circle360TriggerClose(CLK := g_bCircle360CenterCloseM);
IF R_Circle360Trigger.Q THEN
  g_bCircle360CenterM := FALSE;
  nCircle360Switch := 10;
END_IF;
IF R_Circle360TriggerClose.Q THEN
  g_bCircle360CenterCloseM := FALSE;
  IF nCircle360Switch=20 THEN(*开着的情况再去关*)
    nCircle360Switch := 50;
  END_IF;

END_IF;

CASE nCircle360Switch OF
  0:
    nCircle360Switch := 0;
  10:(*随动已开始，将数据同步*)
    dZPosCurPos := g_fZCoordinate;
    dZPosTop := g_fZCoordinate;
    dZPosLow := g_fZCoordinate;
    nCircle360Switch := 20;
  20:(*随动已开始，实时记录下当前Z轴机械坐标*)
    dZPosCurPos := g_fZCoordinate;
    IF dZPosCurPos > dZPosTop THEN(*大于最大值，取最大值*)
      dZPosTop := dZPosCurPos;
    END_IF;
    IF dZPosCurPos < dZPosLow THEN(*小于最小值，取最小值*)
      dZPosLow := dZPosCurPos;
    END_IF;
  50:(*将最高点和最低点记录好并传出*)
    g_foCurZPosOutPut1 := dZPosTop;
    g_foCurZPosOutPut2 := dZPosLow;
    nCircle360Switch := 0;
END_CASE;


(*第二阶段：高处关随动检测Z轴高度*)
R_NoFllowFindTop(CLK := g_bCircleFindTopNoFollowM);
R_NoFllowFindTopClose(CLK := g_bCircleFindTopNoFollowCloseM);

IF R_NoFllowFindTop.Q THEN
  g_bCircleFindTopNoFollowM := FALSE;
  dZPosCurPos := g_fZCoordinate;
  dZPosLastPos := g_fZCoordinate;
  dZPosTop := g_fZCoordinate;
  dZPosLow := g_fZCoordinate;
  IF g_fCircleFindTopNoFollowModeM=0.0 THEN(*记录圆管Z轴坐标*)
    nCircleTopNoFollowSwitch := 50;
  ELSIF g_fCircleFindTopNoFollowModeM=1.0 THEN(*寻找Z最高点*)
    nCircleTopNoFollowSwitch := 10;
    g_foCircleFindTopDoneXPos := g_diXMachineCoordinate;
  END_IF;
END_IF;
IF R_NoFllowFindTopClose.Q THEN
  g_bCircleFindTopNoFollowCloseM := FALSE;
  nCircleTopNoFollowSwitch := 0;
END_IF;

CASE nCircleTopNoFollowSwitch OF
  0:
    nCircleTopNoFollowSwitch := 0;
  10:(*外部随动已完成，获取到Z轴最高点*)
    dZPosCurPos := g_fZCoordinate;
    (*检测随动后，Z轴坐标的最高点即为中心点*)(*参数过滤？*)
    IF (dZPosCurPos > dZPosLastPos) AND (dZPosTop < dZPosCurPos) THEN
      dZPosTop := dZPosCurPos;
      dXPosTop := g_diXMachineCoordinate;
      g_foCircleFindTopDoneXPos := dXPosTop;(*传出去*) 
    END_IF;
    dZPosLastPos := dZPosCurPos;
  50:(*获取圆管中心*)
     (*卡盘中心坐标 = 当前Z轴坐标 - 随动高度 - 管高半径*)
      g_dChuckCenterInZpos:= g_fZCoordinate-1.0-(g_fLevelAndCenterHight/2.0);(*待优化，目前随动高度固定为1 *)
      nCircleTopNoFollowSwitch := 0;
END_CASE;

g_doCricleCenterZPosCurPos := dZPosCurPos;
g_doCricleCenterZPosLastPos := dZPosLastPos;
g_doCricleCenterZPosTop := dZPosTop;
g_noCircleTopNoFollowSwitch := nCircleTopNoFollowSwitch;
